package earth.terrarium.pastel.data.lang.guidebook.creatinglife;

import net.neoforged.neoforge.common.data.LanguageProvider;

public class DragonboneEntry {
	public static void addTranslations(LanguageProvider provider) {
		provider.add("book.pastel.guidebook.dragonbone.page0.text", "Is it really dragons these giant remnants come from?\\\nI don't know, honestly. But judging by their size, they could very well be!\\\n\\\nEven now, these blocks are surrounded by a magical aura, protecting them from blatant mining attempts. I had a *blast* just running my fingers over their rough surface.");
		provider.add("book.pastel.guidebook.dragonbone.page1.text", "Damaging Dragonbone using [#](449900)Explosions[#]() seems to blow away the magical aura protecting them, finally making the blocks mineable.\\\nThe dropped pieces still retain some of that ancient magic.");
		provider.add("book.pastel.guidebook.dragonbone.page2.text", "The [Cinderhearth](entry://ink/cinderhearth) is the only thing that generates enough heat to turn these bones to ash.");
		provider.add("book.pastel.guidebook.dragonbone.page2.title", "Turning to Ash");
		provider.add("book.pastel.guidebook.dragonbone.page6.text", "Most blocks can be returned to their polished form via the [Cinderhearth](entry://ink/cinderhearth).");
		provider.add("book.pastel.guidebook.dragonbone.anvil_crushing.text", "While the bones are pretty sturdy, enough force is still able to pulverize them, making for an exceptional fertilizer.");
		provider.add("book.pastel.guidebook.dragonbone.dragonrot_converting.text", "This pairing is ironic, in a way. What seems morbid, like breading chicken with egg, ends up as a dragon - dragon = ...nothing. It's just... ash.");
	}
}
